"use client";

import { AnimatePresence, m, useReducedMotion } from "motion/react";
import {
  skillLabel,
  useSkillCatalog,
} from "../../lib/capabilities/skill-catalog";
import {
  useMemo,
  useEffect,
  useLayoutEffect,
  useState,
  useRef,
  type ReactNode,
} from "react";
import { ChevronDown, Puzzle } from "lucide-react";
import { cn, useAomiRuntime } from "@aomi-labs/react";
import { getSkillIcon } from "../icons/skills";
import { selectActivity, type ActivityTransaction } from "./model";
import { SubagentRow } from "./subagent-row";
import { TransactionCard, TransactionList } from "./transactions";
import { WalletReview } from "./wallet-review";
import { useActivityPanel } from "./activity-panel-context";

export function ActivitySidebar() {
  const { threadViewKey } = useAomiRuntime();
  return <ActivitySidebarContent key={threadViewKey} />;
}

function ActivitySidebarContent() {
  const { events, pendingActions, actionAttempts, threadViewKey, isRunning } =
    useAomiRuntime();
  const reduceMotion = useReducedMotion();
  const {
    open: panelOpen,
    setOpen: setPanelOpen,
    setWorthShowing,
  } = useActivityPanel();
  const [open, setOpen] = useState(true);
  const [compact, setCompact] = useState(false);
  const anchorRef = useRef<HTMLSpanElement>(null);
  const railRef = useRef<HTMLElement>(null);
  const layoutParent = useRef<HTMLElement | null>(null);
  useEffect(
    () => () => {
      layoutParent.current?.style.removeProperty("--activity-chat-max-width");
    },
    [],
  );
  useLayoutEffect(() => {
    const parent = anchorRef.current?.parentElement;
    if (!parent || typeof ResizeObserver === "undefined") return;
    const update = () => setCompact(parent.clientWidth < 1100);
    update();
    const observer = new ResizeObserver(update);
    observer.observe(parent);
    return () => observer.disconnect();
  }, []);
  const activity = useMemo(
    () => selectActivity(events, pendingActions),
    [events, pendingActions],
  );
  const pending = pendingActions[0];
  const signing = Boolean(
    pending &&
    (pending.request.type === "sign" ||
      (pending.request.simulation.status !== "failed" &&
        !pending.request.simulation.guards.some(
          (guard) => guard.status === "failed",
        ))),
  );
  const expanded = signing || open;
  const current = activity.transactions.filter(
    (tx) =>
      (!tx.action || tx.action.state === "pending") &&
      (!pending || tx.action?.id === pending.id),
  );
  const transactions = [
    ...new Map(
      [...activity.transactions, ...activity.history].map((tx) => [tx.id, tx]),
    ).values(),
  ].sort(
    (a, b) =>
      (b.sequence ?? b.action?.sequence ?? 0) -
        (a.sequence ?? a.action?.sequence ?? 0) ||
      (b.actionIndex ?? 0) - (a.actionIndex ?? 0),
  );
  const card = (tx: ActivityTransaction, historical = false) => (
    <TransactionCard
      key={tx.id}
      transaction={tx}
      reviewing={Boolean(pending && tx.action?.id === pending.id)}
      active={
        !historical &&
        tx.turnId === activity.turnId &&
        (isRunning ||
          pendingActions.some((action) => action.id === tx.action?.id))
      }
      executing={
        !historical &&
        Boolean(
          tx.action &&
          ["executing", "responding"].includes(
            actionAttempts.get(tx.action.id)?.state ?? "",
          ),
        )
      }
    />
  );
  const hasActivity = Boolean(
    activity.agents.length ||
    activity.skills.length ||
    activity.transactions.length ||
    activity.history.length ||
    pendingActions.length,
  );
  useEffect(() => {
    setWorthShowing(hasActivity, Boolean(pending));
  }, [hasActivity, pending, setWorthShowing]);
  useEffect(() => () => setWorthShowing(false, false), [setWorthShowing]);
  const showRail = hasActivity && panelOpen;
  return (
    <>
      <span ref={anchorRef} className="hidden" aria-hidden="true" />
      <AnimatePresence>
        {showRail && (
          <m.aside
            ref={railRef}
            onUpdate={(latest) => {
              const parent = railRef.current?.parentElement;
              if (!parent || typeof latest.width !== "number") return;
              layoutParent.current = parent;
              const progress = Math.max(0, Math.min(1, latest.width / 352));
              parent.style.setProperty(
                "--activity-chat-max-width",
                `calc(100% - (100cqw - 960px) * ${progress})`,
              );
            }}
            key={threadViewKey ?? "activity"}
            initial={{ width: 0, opacity: 0 }}
            animate={{ width: 352, opacity: 1 }}
            exit={{ width: 0, opacity: 0 }}
            transition={{
              duration: reduceMotion ? 0 : 0.32,
              ease: [0.22, 1, 0.36, 1],
            }}
            aria-label="Chat activity"
            onKeyDown={(event) => {
              if (event.key === "Escape" && compact) {
                setPanelOpen(false);
              }
            }}
            className={cn(
              "aui-activity-sidebar max-h-full max-w-full shrink-0 overflow-y-auto overflow-x-hidden",
              compact ? "absolute right-0 top-0 z-30" : "relative top-0 block",
            )}
          >
            <div className="w-[352px] max-w-[100cqw] py-4 pl-3 pr-6">
              <div className="border-aomi-border bg-aomi-raised divide-aomi-border divide-y rounded-3xl border px-4">
                {activity.agents.length > 0 && (
                  <Group title="Subagents" count={activity.agents.length}>
                    {activity.agents.map((agent, index) => (
                      <SubagentRow
                        key={agent.agentId}
                        agent={agent}
                        index={index}
                      />
                    ))}
                  </Group>
                )}
                {activity.skills.length > 0 && (
                  <Group title="Skills" count={activity.skills.length}>
                    <InvokedSkills ids={activity.skills} />
                  </Group>
                )}
                {(transactions.length > 0 || pending) && (
                  <section className="py-4" aria-label="Transactions">
                    {signing ? (
                      <h2 className="mb-3 flex items-center gap-2 text-[13px] font-medium">
                        Transactions{" "}
                        <span className="text-aomi-muted font-normal">
                          {transactions.length}
                        </span>
                      </h2>
                    ) : (
                      <button
                        type="button"
                        aria-expanded={expanded}
                        onClick={() => setOpen(!open)}
                        className="mb-3 flex w-full items-center gap-2 text-[13px] font-medium"
                      >
                        Transactions{" "}
                        <span className="text-aomi-muted font-normal">
                          {transactions.length}
                        </span>
                        <ChevronDown
                          className={cn(
                            "text-aomi-muted ml-auto size-3.5 transition-transform motion-reduce:transition-none",
                            expanded && "rotate-180",
                          )}
                        />
                      </button>
                    )}
                    <AnimatePresence initial={false}>
                      {expanded && (
                        <m.div
                          key="transaction-content"
                          initial={{ height: 0, opacity: 0 }}
                          animate={{ height: "auto", opacity: 1 }}
                          exit={{ height: 0, opacity: 0 }}
                          transition={{
                            duration: reduceMotion ? 0 : 0.22,
                            ease: "easeOut",
                          }}
                          className="overflow-hidden"
                        >
                          <TransactionList
                            newestId={transactions[0]?.id}
                            count={transactions.length}
                          >
                            {transactions.map((tx) =>
                              card(
                                tx,
                                Boolean(
                                  tx.action
                                    ? tx.action.state !== "pending"
                                    : tx.turnId !== activity.turnId,
                                ),
                              ),
                            )}
                          </TransactionList>
                          {pending && transactions.length > current.length && (
                            <p className="text-aomi-muted mt-3 text-[11px]">
                              Wallet request: {current.length} transaction
                              {current.length === 1 ? "" : "s"}.
                            </p>
                          )}
                          {pending && (
                            <WalletReview
                              key={`${pending!.id}:${pending!.revision}`}
                            />
                          )}
                        </m.div>
                      )}
                    </AnimatePresence>
                  </section>
                )}
              </div>
            </div>
          </m.aside>
        )}
      </AnimatePresence>
    </>
  );
}

function Group({
  title,
  count,
  children,
}: {
  title: string;
  count: number;
  children: ReactNode;
}) {
  const [open, setOpen] = useState(true);

  return (
    <section className="py-4" aria-label={title}>
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen((current) => !current)}
        className="flex w-full items-center gap-2 text-left text-[13px] font-medium"
      >
        {title}
        <span className="text-aomi-muted font-normal tabular-nums">
          {count}
        </span>
        <ChevronDown
          className={cn(
            "text-aomi-muted ml-auto size-3.5 transition-transform duration-200 ease-out motion-reduce:transition-none",
            open && "rotate-180",
          )}
        />
      </button>
      <div
        aria-hidden={!open}
        inert={!open}
        data-activity-group-content={title}
        className={cn(
          "grid transition-[grid-template-rows,opacity] duration-200 ease-out motion-reduce:transition-none",
          open ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0",
        )}
      >
        <div className="min-h-0 overflow-hidden">
          <div className="pt-3">{children}</div>
        </div>
      </div>
    </section>
  );
}

function InvokedSkills({ ids }: { ids: string[] }) {
  const { skills } = useSkillCatalog();
  return (
    <div className="flex flex-wrap gap-2">
      {ids.map((id) => {
        const Icon = getSkillIcon(id) ?? Puzzle;
        const skill = skills?.find((skill) => skill.id === id);
        const label = skillLabel(
          skill ?? {
            name:
              id === "common_erc20"
                ? "ERC-20"
                : id === "lifi_swap"
                  ? "LI.FI"
                  : id,
          },
        );
        return (
          <span
            key={id}
            title={label}
            className="border-aomi-border bg-aomi-surface inline-flex max-w-full items-center gap-2 rounded-2xl border px-3 py-2 text-[12px]"
          >
            <Icon className="size-4 shrink-0" />
            <span className="truncate">{label}</span>
          </span>
        );
      })}
    </div>
  );
}

"use client";

import { useState } from "react";
import { Bot, Check, CircleAlert, LoaderCircle } from "lucide-react";
import { cn, type TaskRunState } from "@aomi-labs/react";
import { TextMessagePartProvider } from "@assistant-ui/react";
import { MarkdownText } from "@/components/assistant-ui/markdown-text";

export function SubagentRow({
  agent,
  index,
}: {
  agent: TaskRunState;
  index: number;
}) {
  const [open, setOpen] = useState(false);
  const hasMessage = Boolean(agent.message?.trim());
  const label = agent.label || agent.app || "Subagent";
  const status =
    agent.status === "completed"
      ? "Completed"
      : agent.status === "running"
        ? "Working"
        : agent.status === "failed"
          ? "Failed"
          : agent.status === "cancelled"
            ? "Cancelled"
            : "Stalled";

  return (
    <section className="py-2" aria-label={label}>
      <button
        type="button"
        aria-expanded={hasMessage ? open : undefined}
        aria-controls={hasMessage ? `subagent-${agent.agentId}` : undefined}
        onClick={() => hasMessage && setOpen((current) => !current)}
        className={cn(
          "flex w-full items-center gap-2.5 text-left",
          hasMessage ? "cursor-pointer" : "cursor-default",
        )}
      >
        <Bot
          aria-hidden="true"
          className={cn(
            "size-4 shrink-0",
            index % 2 ? "text-pink-500" : "text-aomi-accent",
          )}
        />
        <span className="min-w-0 flex-1 truncate text-[13px]" title={label}>
          {label}
        </span>
        <SubagentStatus status={agent.status} label={status} />
      </button>
      {hasMessage && (
        <div
          id={`subagent-${agent.agentId}`}
          aria-hidden={!open}
          inert={!open}
          data-subagent-content={agent.agentId}
          className={cn(
            "grid transition-[grid-template-rows,opacity] duration-200 ease-out motion-reduce:transition-none",
            open ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0",
          )}
        >
          <div className="min-h-0 overflow-hidden">
            <div className="text-aomi-muted overflow-hidden break-words pl-[26px] pt-2 text-[12px] leading-5 [&_.aui-md>*:first-child]:mt-0 [&_.aui-md>*:last-child]:mb-0 [&_.aui-md]:text-[12px] [&_.aui-md]:leading-5">
              <TextMessagePartProvider text={agent.message!} isRunning={false}>
                <MarkdownText />
              </TextMessagePartProvider>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

function SubagentStatus({
  status,
  label,
}: {
  status: TaskRunState["status"];
  label: string;
}) {
  return (
    <span
      role="status"
      aria-label={label}
      title={label}
      className={cn(
        "grid size-5 shrink-0 place-items-center",
        status === "completed"
          ? "text-aomi-success"
          : status === "failed"
            ? "text-aomi-danger"
            : status === "running"
              ? "text-aomi-accent"
              : "text-aomi-muted",
      )}
    >
      {status === "completed" ? (
        <Check aria-hidden="true" className="size-4" strokeWidth={2.2} />
      ) : status === "running" ? (
        <LoaderCircle
          aria-hidden="true"
          className="size-4 animate-spin motion-reduce:animate-none"
        />
      ) : (
        <CircleAlert aria-hidden="true" className="size-4" />
      )}
    </span>
  );
}

"use client";

import {
  createElement,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { m, useReducedMotion } from "motion/react";
import { Circle, FileSignature, Layers3 } from "lucide-react";
import { cn, getChainInfo } from "@aomi-labs/react";
import { getChainIcon } from "../icons/chain-map";
import type { ActivityTransaction } from "./model";
import { friendlyTransactionLabel, transactionSemantic } from "./presentation";

export function TransactionList({
  children,
  newestId,
  count,
}: {
  children: ReactNode;
  newestId?: string;
  count: number;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [showAll, setShowAll] = useState(false);
  const reduceMotion = useReducedMotion();
  const [edges, setEdges] = useState({ top: false, bottom: false });
  useEffect(() => {
    if (ref.current) {
      ref.current.scrollTop = 0;
    }
  }, [newestId]);
  const update = () => {
    const el = ref.current;
    if (el)
      setEdges({
        top: el.scrollTop > 2,
        bottom: el.scrollHeight - el.clientHeight - el.scrollTop > 2,
      });
  };
  useEffect(() => {
    update();
    const el = ref.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(update);
    observer.observe(el);
    if (el.firstElementChild) observer.observe(el.firstElementChild);
    return () => observer.disconnect();
  }, [children]);
  return (
    <div>
      <div className="relative">
        <m.div
          ref={ref}
          initial={false}
          animate={{
            height: Math.max(
              0,
              (showAll ? count : Math.min(3, count)) * 94 - 10,
            ),
          }}
          transition={{ duration: reduceMotion ? 0 : 0.26, ease: "easeOut" }}
          onScroll={update}
          tabIndex={0}
          role="region"
          aria-label="Transactions, newest first"
          className="aui-current-transactions overflow-y-auto overscroll-contain rounded-2xl outline-offset-2 [overflow-anchor:none]"
        >
          <div className="space-y-2.5">{children}</div>
        </m.div>
        <div
          aria-hidden="true"
          data-scroll-fade="top"
          className={cn(
            "from-aomi-raised pointer-events-none absolute inset-x-0 top-0 h-5 rounded-t-2xl bg-gradient-to-b to-transparent transition-opacity motion-reduce:transition-none",
            edges.top ? "opacity-100" : "opacity-0",
          )}
        />
        <div
          aria-hidden="true"
          data-scroll-fade="bottom"
          className={cn(
            "from-aomi-raised pointer-events-none absolute inset-x-0 bottom-0 h-5 rounded-b-2xl bg-gradient-to-t to-transparent transition-opacity motion-reduce:transition-none",
            edges.bottom ? "opacity-100" : "opacity-0",
          )}
        />
      </div>
      {count > 3 && (
        <button
          type="button"
          aria-expanded={showAll}
          onClick={() => {
            if (ref.current) ref.current.scrollTop = 0;
            setShowAll(!showAll);
          }}
          className="text-aomi-muted hover:text-aomi-fg mt-2 flex items-center gap-2 py-1 text-[12px] transition-colors motion-reduce:transition-none"
        >
          <span aria-hidden="true">⋯</span>
          {showAll
            ? "Show fewer transactions"
            : `Show all ${count} transactions`}
        </button>
      )}
    </div>
  );
}

export function TransactionCard({
  transaction: tx,
  reviewing = false,
  executing,
  active,
}: {
  transaction: ActivityTransaction;
  reviewing?: boolean;
  executing: boolean;
  active: boolean;
}) {
  const reduceMotion = useReducedMotion();
  const label = friendlyTransactionLabel(tx.label, tx.kind);
  const Icon =
    tx.kind === "signature"
      ? FileSignature
      : (transactionSemantic(label, tx.kind).Icon ?? Layers3);
  const Chain = useMemo(
    () => (tx.chainId ? (getChainIcon(tx.chainId) ?? Circle) : Circle),
    [tx.chainId],
  );
  const network = tx.chainId
    ? (getChainInfo(tx.chainId)?.name ?? `Chain ${tx.chainId}`)
    : (tx.cluster ?? "Solana");
  const step = tx.stage === "staged" ? 0 : tx.stage === "committed" ? 2 : 1;
  const result = tx.action?.result;
  const leg =
    result?.status === "submitted"
      ? result.legs.find((leg) => leg.id === `leg_${(tx.actionIndex ?? 0) + 1}`)
      : undefined;
  const signed =
    leg?.status === "submitted" ||
    (result?.status === "signed" && result.outputs.length > 0);
  const rejected =
    leg?.status === "rejected" ||
    result?.status === "rejected" ||
    tx.action?.state === "rejected";
  const failed =
    tx.stage === "simulation-failed" ||
    (tx.action?.request.type !== "sign" &&
      (tx.action?.request.simulation.status === "failed" ||
        tx.action?.request.simulation.guards.some(
          (guard) => guard.status === "failed",
        )));
  const terminal = tx.action && tx.action.state !== "pending";
  const animating =
    (active || executing) && !signed && !rejected && !failed && !terminal;
  const animatedStep = executing ? 3 : step;
  const pendingStyle =
    !signed &&
    !rejected &&
    !terminal &&
    (active || tx.action?.state === "pending");
  return (
    <div
      className={cn(
        "group/tx bg-aomi-surface flex h-[84px] flex-col justify-center rounded-2xl border px-3 py-3 transition-colors duration-200 motion-reduce:transition-none",
        pendingStyle
          ? reviewing
            ? "border-aomi-accent/50 border-dashed"
            : "border-aomi-muted/40 border-dashed"
          : "border-aomi-border",
      )}
      data-pending={pendingStyle || undefined}
      aria-description={
        reviewing && pendingStyle
          ? "Included in the current wallet request"
          : undefined
      }
      data-testid="activity-transaction"
    >
      <div>
        <div className="flex items-center gap-2">
          <Icon className="text-aomi-muted size-4 shrink-0" />
          <span
            className="min-w-0 flex-1 truncate text-[13px] font-medium"
            title={label}
          >
            {label}
          </span>
          <span
            className="bg-aomi-surface-2 text-aomi-muted inline-flex max-w-[100px] items-center gap-1.5 rounded-full px-2 py-1 text-[10px]"
            title={network}
          >
            {createElement(Chain, { className: "size-3 shrink-0" })}
            <span className="truncate">{network}</span>
          </span>
        </div>
        <div
          className="mt-2.5 grid grid-cols-4 gap-1.5"
          aria-label={`Transaction preparation: ${tx.stage}; signing: ${rejected ? "rejected" : signed ? "signed" : "not signed"}`}
        >
          {["Stage", "Simulate", "Commit", "Signed"].map((name, index) => (
            <div
              key={name}
              title={
                index === 3
                  ? rejected
                    ? "Signing rejected"
                    : signed
                      ? "Signed"
                      : "Not yet signed"
                  : name
              }
            >
              <m.div
                data-active-phase={
                  (animating && index === animatedStep) || undefined
                }
                style={
                  animating && index === animatedStep
                    ? {
                        backgroundImage:
                          "linear-gradient(90deg, var(--aomi-accent-subtle), var(--aomi-accent), var(--aomi-accent-subtle))",
                        backgroundSize: "200% 100%",
                      }
                    : undefined
                }
                animate={{
                  backgroundPosition:
                    animating && index === animatedStep && !reduceMotion
                      ? ["0% 0%", "-200% 0%"]
                      : "0% 0%",
                }}
                transition={{
                  duration: 1.3,
                  ease: "linear",
                  repeat:
                    animating && index === animatedStep && !reduceMotion
                      ? Infinity
                      : 0,
                }}
                className={cn(
                  "h-[3px] rounded-full transition-colors motion-reduce:transition-none",
                  (index === 1 && failed) || (index === 3 && rejected)
                    ? "bg-aomi-danger"
                    : index === 1 && tx.kind === "signature"
                      ? "bg-aomi-border"
                      : index <= step || (index === 3 && signed)
                        ? "bg-aomi-accent"
                        : "bg-aomi-border",
                )}
              />
              <span className="text-aomi-muted mt-1.5 block text-[10px] leading-3">
                {name}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
  type FC,
  type ReactNode,
} from "react";

type ActivityPanelContextValue = {
  worthShowing: boolean;
  reviewing: boolean;
  open: boolean;
  setOpen: (open: boolean) => void;
  setWorthShowing: (worthShowing: boolean, reviewing: boolean) => void;
};

const ActivityPanelContext = createContext<ActivityPanelContextValue>({
  worthShowing: false,
  reviewing: false,
  // Standalone ActivitySidebar renders stay visible; AomiFrame supplies the
  // managed provider whose compact state starts closed.
  open: true,
  setOpen: () => undefined,
  setWorthShowing: () => undefined,
});

export const ActivityPanelProvider: FC<{ children: ReactNode }> = ({
  children,
}) => {
  const [open, setOpen] = useState(false);
  const [activityState, setActivityState] = useState({
    worthShowing: false,
    reviewing: false,
  });
  const worthShowingRef = useRef(false);
  const setWorthShowing = useCallback(
    (worthShowing: boolean, reviewing: boolean) => {
      const becameWorthShowing = worthShowing && !worthShowingRef.current;
      worthShowingRef.current = worthShowing;
      setActivityState((current) =>
        current.worthShowing === worthShowing && current.reviewing === reviewing
          ? current
          : { worthShowing, reviewing },
      );
      if (becameWorthShowing) setOpen(true);
      else if (!worthShowing) setOpen(false);
    },
    [],
  );
  const value = useMemo(
    () => ({ ...activityState, open, setOpen, setWorthShowing }),
    [activityState, open, setWorthShowing],
  );

  return (
    <ActivityPanelContext.Provider value={value}>
      {children}
    </ActivityPanelContext.Provider>
  );
};

export const useActivityPanel = (): ActivityPanelContextValue =>
  useContext(ActivityPanelContext);

import type { Action, Event } from "@aomi-labs/client";
import { selectTaskRuns } from "@aomi-labs/react";
import { unwrapToolStep } from "../assistant-ui/tool-interpreter/unwrap";

type RecordValue = Record<string, unknown>;
export type ActivityTransaction = {
  id: string;
  sequence?: number;
  turnId: string | null;
  family: "evm" | "svm";
  label: string;
  kind: string;
  chainId?: number;
  cluster?: string;
  raw: RecordValue;
  stage: "staged" | "simulated" | "simulation-failed" | "committed";
  action?: Action;
  actionIndex?: number;
  committedWire?: string;
};

function record(value: unknown): RecordValue | undefined {
  if (typeof value === "string") {
    try {
      return record(JSON.parse(value));
    } catch {
      return undefined;
    }
  }
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as RecordValue)
    : undefined;
}
const string = (value: unknown) =>
  typeof value === "string" ? value : undefined;
const number = (value: unknown) =>
  typeof value === "number" ? value : undefined;
const ids = (value: unknown): number[] =>
  Array.isArray(value)
    ? value.filter((id): id is number => typeof id === "number")
    : [];

/** Only complete tool records are projected; streamed child previews are not authoritative. */
function toolRecord(
  event: Event,
): { name: string; result: RecordValue } | undefined {
  let name: string, result: unknown;
  if (event.type === "message" && event.tool_result) {
    name = event.tool_name ?? event.tool_result[0];
    result = record(event.tool_result[1]);
  } else if (event.type === "tool_complete" || event.type === "tool_update") {
    name = event.tool_name;
    result = record(event.result);
  } else return;
  const unwrapped = unwrapToolStep({ toolName: name, result }).resultRecord;
  return unwrapped ? { name, result: unwrapped } : undefined;
}

function sameInstruction(raw: RecordValue, ix: RecordValue): boolean {
  return (
    Boolean(raw.program_id) &&
    ix.program_id === raw.program_id &&
    ix.data_base64 === raw.data_base64 &&
    JSON.stringify(ix.accounts) === JSON.stringify(raw.accounts)
  );
}

/** Match immutable transaction content, never labels or the ordinal in a batch. */
function sameTransaction(
  staged: ActivityTransaction,
  action: Action,
  index: number,
): boolean {
  const request = action.request;
  if (request.type === "execute_evm" && staged.family === "evm") {
    const tx = request.transactions[index];
    const raw = staged.raw;
    return (
      tx.chain_id === raw.chain_id &&
      tx.from.toLowerCase() === string(raw.from)?.toLowerCase() &&
      tx.to.toLowerCase() === string(raw.to)?.toLowerCase() &&
      tx.data.toLowerCase() === string(raw.data)?.toLowerCase() &&
      (tx.value ?? "0") === (raw.value ?? "0")
    );
  }
  if (request.type === "execute_svm" && staged.family === "svm") {
    const tx = request.transactions[index];
    if (
      tx.unsigned_transaction_base64 &&
      tx.unsigned_transaction_base64 === staged.committedWire
    )
      return true;
    if (
      tx.unsigned_transaction_base64 &&
      tx.unsigned_transaction_base64 ===
        staged.raw.unsigned_transaction_base64 &&
      tx.cluster === staged.cluster &&
      tx.payer === staged.raw.payer
    )
      return true;
    // Lane 1 instructions become one transaction at commit. Compare instruction
    // content after the backend strips its internal pending/lifecycle fields.
    const raw = staged.raw;
    return (
      tx.cluster === staged.cluster &&
      tx.payer === raw.payer &&
      Boolean(raw.program_id) &&
      tx.instructions.some((value) =>
        sameInstruction(raw, value as RecordValue),
      )
    );
  }
  return false;
}

export function selectActivity(
  events: readonly Event[],
  pendingActions: readonly Action[] = [],
) {
  const ordered = [...events].sort((a, b) => a.sequence - b.sequence);
  const turnId =
    [...ordered]
      .reverse()
      .find(
        (event) =>
          event.type === "message" && event.sender === "user" && event.turn_id,
      )?.turn_id ??
    [...ordered].reverse().find((event) => event.turn_id)?.turn_id ??
    null;
  const skills = new Set<string>();
  const staged = new Map<string, ActivityTransaction>();
  const actions = new Map<string, Action>();
  const actionOrder = new Map<string, number>();
  for (const event of ordered) {
    if (event.type === "action") {
      if (!actionOrder.has(event.id)) actionOrder.set(event.id, event.sequence);
      const prior = actions.get(event.id);
      if (!prior || prior.revision <= event.revision)
        actions.set(event.id, event);
      continue;
    }
    const tool = toolRecord(event);
    if (!tool || tool.result.error || tool.result.is_error === true) continue;
    const { name, result } = tool;
    if (Array.isArray(result.activated)) {
      for (const id of result.activated)
        if (typeof id === "string") skills.add(id);
    }
    const family =
      /svm|solana|jupiter/.test(name) || result.chain_kind === "svm"
        ? "svm"
        : "evm";
    // SVM staging wraps the assembled transaction in `tx` or `ix`.
    const stagedRecords = Array.isArray(result.instructions)
      ? result.instructions
      : [record(result.tx) ?? record(result.ix) ?? result];
    for (const raw of stagedRecords) {
      const tx = record(raw);
      if (!tx) continue;
      const pendingId = number(tx.pending_tx_id) ?? number(tx.pending_ix_id);
      if (pendingId != null && tx.current_lifecycle === "queued") {
        const id = `${event.turn_id}:${family}:${pendingId}`;
        const previous = staged.get(id);
        staged.set(id, {
          id,
          sequence: previous?.sequence ?? event.sequence,
          turnId: event.turn_id,
          family,
          label:
            string(tx.label) ??
            string(tx.description) ??
            `Transaction ${pendingId}`,
          kind: string(tx.kind) ?? "transaction",
          chainId: number(tx.chain_id),
          cluster: string(tx.cluster),
          raw: tx,
          stage: previous?.stage ?? "staged",
        });
      }
    }
    if (name === "jupiter_prepare_swap")
      for (const id of ids(result.ix_ids)) {
        const key = `${event.turn_id}:svm:${id}`;
        if (!staged.has(key))
          staged.set(key, {
            id: key,
            sequence: event.sequence,
            turnId: event.turn_id,
            family: "svm",
            label: string(result.description) ?? "Jupiter swap instruction",
            kind: "swap",
            cluster: string(result.cluster),
            raw: result,
            stage: "staged",
          });
      }
    const sim = record(result.simulation);
    if (sim) {
      const affected = ids(
        result.resolved_ids ??
          result.tx_ids ??
          result.ix_ids ??
          (typeof result.tx_id === "number" ? [result.tx_id] : []),
      );
      const success =
        typeof sim.batch_success === "boolean"
          ? sim.batch_success
          : "err" in sim
            ? sim.err == null
            : undefined;
      if (success !== undefined)
        for (const id of affected) {
          const item = staged.get(`${event.turn_id}:${family}:${id}`);
          if (item && !item.action)
            item.stage = success ? "simulated" : "simulation-failed";
        }
    }
    if (
      ["pending_approval", "broadcast_inflight", "aa_sign_request"].includes(
        String(result.status),
      )
    ) {
      for (const id of ids(
        result.tx_ids ?? result.svm_ix_ids ?? result.ix_ids,
      )) {
        const item = staged.get(`${event.turn_id}:${family}:${id}`);
        if (item) {
          item.stage = "committed";
          item.committedWire = string(result.unsigned_tx);
        }
      }
    }
  }
  for (const action of pendingActions) {
    const previous = actions.get(action.id);
    if (!previous || previous.revision <= action.revision)
      actions.set(action.id, action);
  }
  const transactions = [...staged.values()];
  for (const action of actions.values()) {
    const request = action.request;
    const count = request.type === "sign" ? 1 : request.transactions.length;
    for (let index = 0; index < count; index++) {
      let matches = transactions.filter(
        (tx) =>
          !tx.action &&
          tx.turnId === action.turn_id &&
          sameTransaction(tx, action, index),
      );
      if (
        request.type === "execute_svm" &&
        matches.length > 1 &&
        !matches[0].committedWire
      ) {
        // Preserve multiplicity: two identical staged instructions do not both
        // become signed when the assembled transaction contains only one.
        const candidates = [...matches];
        matches = [];
        for (const ix of request.transactions[index].instructions) {
          const found = candidates.findIndex((candidate) =>
            sameInstruction(candidate.raw, ix as RecordValue),
          );
          if (found >= 0) matches.push(...candidates.splice(found, 1));
        }
        if (!matches.length && candidates.length) matches = [candidates[0]];
      }
      const match = matches[0];
      if (match) {
        Object.assign(match, {
          stage: "committed",
          sequence:
            match.sequence ?? actionOrder.get(action.id) ?? action.sequence,
          turnId: action.turn_id,
          action,
          actionIndex: index,
        });
        if (request.type === "execute_svm") {
          const assembled = request.transactions[index];
          match.label = assembled.description || match.label;
          match.raw = assembled as unknown as RecordValue;
          for (const duplicate of matches.slice(1))
            transactions.splice(transactions.indexOf(duplicate), 1);
        }
        continue;
      }
      const raw = (request.type === "sign"
        ? request
        : request.transactions[index]) as unknown as RecordValue;
      transactions.push({
        id: `${action.id}:${index}`,
        sequence: actionOrder.get(action.id) ?? action.sequence,
        turnId: action.turn_id,
        family:
          request.type === "execute_svm" ||
          (request.type === "sign" && request.chainFamily === "svm")
            ? "svm"
            : "evm",
        label:
          string(raw.label) ??
          string(raw.description) ??
          (request.type === "sign"
            ? "Sign wallet request"
            : `Transaction ${index + 1}`),
        kind:
          request.type === "sign"
            ? "signature"
            : (string(raw.kind) ?? "transaction"),
        chainId: number(raw.chain_id) ?? number(raw.chainId),
        cluster: string(raw.cluster),
        raw,
        stage: "committed",
        action,
        actionIndex: index,
      });
    }
  }
  return {
    turnId,
    agents: Object.values(selectTaskRuns(ordered)),
    skills: [...skills],
    history: transactions.filter((tx) =>
      tx.action ? tx.action.state !== "pending" : tx.turnId !== turnId,
    ),
    transactions: transactions.filter(
      (tx) => tx.turnId === turnId || tx.action?.state === "pending",
    ),
  };
}

"use client";

import { useCallback, useEffect, useState } from "react";

export type SkillSummary = {
  id: string;
  name: string;
  description: string;
  tags: string[];
  chainIds: number[];
  injectedTools: string[];
  estimatedTokens?: number;
};

export type SkillDetail = SkillSummary & {
  toolNames: string[];
  instructions: string;
  activation?: string;
};

const CATALOG_PATH = "/api/resource/skills?limit=100";
let cachedCatalog: SkillSummary[] | null = null;
let catalogRequest: Promise<SkillSummary[]> | null = null;

function strings(value: unknown): string[] {
  return Array.isArray(value)
    ? value.filter((item): item is string => typeof item === "string")
    : [];
}

function numbers(value: unknown): number[] {
  return Array.isArray(value)
    ? value.filter(
        (item): item is number =>
          typeof item === "number" && Number.isFinite(item),
      )
    : [];
}

function parseSkill(value: unknown): SkillSummary | null {
  if (!value || typeof value !== "object") return null;
  const row = value as Record<string, unknown>;
  if (typeof row.id !== "string" || typeof row.name !== "string") return null;
  return {
    id: row.id,
    name: row.name,
    description: typeof row.description === "string" ? row.description : "",
    tags: strings(row.tags),
    chainIds: numbers(row.chain_ids),
    injectedTools: strings(row.injected_tools),
    ...(typeof row.est_tokens === "number"
      ? { estimatedTokens: row.est_tokens }
      : {}),
  };
}

function parseCatalog(value: unknown): SkillSummary[] {
  if (!value || typeof value !== "object") return [];
  const rows = (value as Record<string, unknown>).skills;
  if (!Array.isArray(rows)) return [];
  return rows
    .map(parseSkill)
    .filter((skill): skill is SkillSummary => skill !== null);
}

async function requestJson(path: string): Promise<unknown> {
  const response = await fetch(path, {
    credentials: "include",
    cache: "no-store",
  });
  if (!response.ok) {
    const text = await response.text();
    throw new Error(text || `Request failed: ${response.status}`);
  }
  return response.json() as Promise<unknown>;
}

export async function fetchSkillCatalog(
  force = false,
): Promise<SkillSummary[]> {
  if (!force && cachedCatalog) return cachedCatalog;
  if (!force && catalogRequest) return catalogRequest;

  const request = requestJson(CATALOG_PATH)
    .then(parseCatalog)
    .then((skills) => {
      cachedCatalog = skills;
      return skills;
    })
    .finally(() => {
      if (catalogRequest === request) catalogRequest = null;
    });
  catalogRequest = request;
  return request;
}

export async function fetchSkillDetail(id: string): Promise<SkillDetail> {
  const value = await requestJson(
    `/api/resource/skills/${encodeURIComponent(id)}`,
  );
  const summary = parseSkill(value);
  if (!summary || !value || typeof value !== "object") {
    throw new Error("Skill details were not available.");
  }
  const row = value as Record<string, unknown>;
  return {
    ...summary,
    toolNames: strings(row.tool_names),
    instructions: typeof row.instructions === "string" ? row.instructions : "",
    ...(typeof row.activation === "string"
      ? { activation: row.activation }
      : {}),
  };
}

export function skillLabel(skill: Pick<SkillSummary, "name">): string {
  return skill.name
    .split(/[-_\s]+/u)
    .filter(Boolean)
    .map((part) => `${part[0]?.toUpperCase() ?? ""}${part.slice(1)}`)
    .join(" ");
}

const CHAIN_CONTEXT =
  /\s+(?:on|from|across)\s+(?:Ethereum|Arbitrum(?: One)?|Optimism|OP Mainnet|Polygon|Base|Linea|Monad|MegaETH|Robinhood|Solana)\b.*$/iu;

/** Turn registry prose into a quiet one-line capability summary for pickers. */
export function conciseSkillDescription(description: string): string {
  const original = description.trim();
  if (!original) return "";

  let summary = original
    .split(/\n|(?<=[.!?])\s/u, 1)[0]!
    .replace(
      /^use (?:this skill )?when (?:the )?users? (?:want|wants|need|needs) (?:to\s+)?/iu,
      "",
    )
    .replace(/\s+[—;].*$/u, "")
    .replace(/\s+via\s+.*$/iu, "")
    .replace(CHAIN_CONTEXT, "")
    .replace(/\bERC20\b/giu, "ERC-20")
    .replace(/[.!?]+$/u, "")
    .trim();

  if (!summary) summary = original;
  summary = `${summary[0]?.toUpperCase() ?? ""}${summary.slice(1)}`;
  if (summary.length <= 64) return summary;

  const boundary = summary.lastIndexOf(" ", 61);
  return `${summary.slice(0, boundary >= 42 ? boundary : 61).trimEnd()}…`;
}

export function useSkillCatalog() {
  const [skills, setSkills] = useState<SkillSummary[] | null>(cachedCatalog);
  const [error, setError] = useState<string | null>(null);
  const [revision, setRevision] = useState(0);

  useEffect(() => {
    let active = true;
    setError(null);
    fetchSkillCatalog(revision > 0)
      .then((rows) => {
        if (active) setSkills(rows);
      })
      .catch(() => {
        if (active) {
          setSkills([]);
          setError("Couldn’t load skills.");
        }
      });
    return () => {
      active = false;
    };
  }, [revision]);

  const retry = useCallback(() => {
    cachedCatalog = null;
    catalogRequest = null;
    setSkills(null);
    setRevision((value) => value + 1);
  }, []);

  return { skills, error, retry, loading: skills === null };
}

import { asRecord } from "./normalize";
import type { ToolContext, ToolStepInput } from "./types";

const parseArgsText = (argsText?: string): unknown => {
  if (!argsText || argsText === "undefined") return undefined;
  try {
    return JSON.parse(argsText);
  } catch {
    return undefined;
  }
};

const unwrapEnvelope = (value: unknown): unknown => {
  const record = asRecord(value);
  if (!record) return value;
  if (record.is_error === true || "error" in record) return value;

  if ("__aomi_tool_value" in record) {
    return unwrapEnvelope(record.__aomi_tool_value);
  }
  if ("__aomi_tool_return" in record) {
    return unwrapEnvelope(record.__aomi_tool_return);
  }
  if ("__aomi_tool_routes" in record && "value" in record) {
    return unwrapEnvelope(record.value);
  }
  if ("RoutedToolReturn" in record && "value" in record) {
    return unwrapEnvelope(record.value);
  }

  return value;
};

export const unwrapToolStep = ({
  toolName,
  argsText,
  result,
  relatedResults,
}: ToolStepInput): ToolContext => {
  const parsedArgs = parseArgsText(argsText);
  const unwrapped =
    typeof result === "string" ? { args: result } : unwrapEnvelope(result);
  const relatedResultRecords = (relatedResults ?? [])
    .map(unwrapEnvelope)
    .map(asRecord)
    .filter((record): record is Record<string, unknown> => record !== null);

  return {
    rawLabel: toolName,
    parsedArgs,
    result: unwrapped,
    resultRecord: asRecord(unwrapped),
    relatedResultRecords,
  };
};

import { getChainInfo, SUPPORTED_CHAINS } from "@aomi-labs/react";

import type { FactRole, FactSource, ToolFact } from "./types";

export const asRecord = (value: unknown): Record<string, unknown> | null =>
  typeof value === "object" && value !== null
    ? (value as Record<string, unknown>)
    : null;

export const asString = (value: unknown): string | undefined =>
  typeof value === "string" && value.length > 0 ? value : undefined;

export const asNumber = (value: unknown): number | undefined =>
  typeof value === "number" && Number.isFinite(value) ? value : undefined;

export const asInteger = (value: unknown): number | undefined => {
  if (typeof value === "number" && Number.isInteger(value)) return value;
  if (typeof value !== "string" || !/^\d+$/.test(value)) return undefined;
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) ? parsed : undefined;
};

export const humanize = (value: string): string => {
  const readable = value
    .replace(/[_-]+/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .trim();
  if (!readable) return "Tool";
  return readable.charAt(0).toUpperCase() + readable.slice(1);
};

export const uniqueFacts = (facts: ToolFact[]): ToolFact[] => {
  const seen = new Set<string>();
  return facts.filter((fact) => {
    const key = `${fact.kind}:${fact.role ?? ""}:${fact.label ?? fact.value}`;
    const normalized = key.toLowerCase();
    if (seen.has(normalized)) return false;
    seen.add(normalized);
    return true;
  });
};

const normalizeChainLabel = (value: string): string =>
  value.toLowerCase().replace(/[_-]+/g, " ").trim();

const chainInfoFromName = (name: string | undefined) => {
  if (!name) return undefined;
  const normalized = normalizeChainLabel(name);
  return SUPPORTED_CHAINS.find(
    (chain) =>
      normalizeChainLabel(chain.name) === normalized ||
      chain.ticker.toLowerCase() === normalized,
  );
};

export const chainFact = (
  chainId: unknown,
  chainName?: unknown,
  source: FactSource = "result",
): ToolFact | null => {
  const id = asNumber(chainId);
  const name = asString(chainName);
  const chain = id != null ? getChainInfo(id) : chainInfoFromName(name);
  const resolvedId = chain?.id ?? id;
  if (resolvedId == null && !name) return null;

  return {
    kind: "chain",
    value: resolvedId != null ? String(resolvedId) : (name ?? ""),
    label: chain?.name ?? (name ? humanize(name) : `chain ${id}`),
    source,
  };
};

export const chainFactFromRecord = (
  record: Record<string, unknown> | null | undefined,
  source: FactSource = "result",
): ToolFact | null => {
  if (!record) return null;
  return chainFact(
    record.chain_id,
    record.chain_name ?? record.chain ?? record.network,
    source,
  );
};

/** Resolve an explicit chain name embedded in a model-authored tool topic.
 * Longest names win, so "Base Sepolia" is not reduced to "Base". Tickers are
 * intentionally excluded because token symbols such as ETH are ambiguous. */
export const chainFactFromText = (
  value: string,
  source: FactSource = "label",
): ToolFact | null => {
  const searchable = ` ${value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()} `;
  const chains = [...SUPPORTED_CHAINS].sort(
    (left, right) => right.name.length - left.name.length,
  );
  const chain = chains.find((candidate) => {
    const name = candidate.name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
    return name.length > 0 && searchable.includes(` ${name} `);
  });
  return chain ? chainFact(chain.id, chain.name, source) : null;
};

const ZERO_ADDRESS = "0x0000000000000000000000000000000000000000";

export const normalizeAddress = (value: unknown): string | null => {
  if (typeof value !== "string") return null;
  const lower = value.toLowerCase();
  return /^0x[a-f0-9]{40}$/.test(lower) ? lower : null;
};

export const addressFact = (
  value: unknown,
  role: FactRole,
  source: FactSource = "result",
): ToolFact | null => {
  const address = normalizeAddress(value);
  if (!address) return null;
  return {
    kind: "address",
    role: address === ZERO_ADDRESS ? "null" : role,
    value: address,
    source,
  };
};

export const tokenFact = (
  symbol: unknown,
  source: FactSource = "result",
): ToolFact | null => {
  const value = asString(symbol);
  return value ? { kind: "token", value, source } : null;
};

export const amountFact = (
  value: unknown,
  unit?: string,
  source: FactSource = "result",
): ToolFact | null => {
  const raw =
    typeof value === "bigint"
      ? value.toString()
      : typeof value === "number" && Number.isFinite(value)
        ? String(value)
        : asString(value);
  if (!raw) return null;
  return {
    kind: "amount",
    value: raw,
    label: unit ? `${raw} ${unit}` : raw,
    source,
  };
};

export const statusFact = (
  value: unknown,
  source: FactSource = "result",
): ToolFact | null => {
  if (value === true) return { kind: "status", value: "success", source };
  if (value === false) return { kind: "status", value: "failed", source };
  const raw = asString(value);
  if (!raw) return null;
  const normalized = raw.toLowerCase().replace(/[_-]+/g, " ");
  if (normalized === "pending approval") {
    return { kind: "status", value: "pending_approval", source };
  }
  if (normalized.includes("pending")) {
    return { kind: "status", value: "pending", source };
  }
  if (normalized.includes("queued")) {
    return { kind: "status", value: "queued", source };
  }
  if (normalized.includes("success") || normalized.includes("complete")) {
    return { kind: "status", value: "success", source };
  }
  if (normalized.includes("fail") || normalized.includes("error")) {
    return { kind: "status", value: "failed", source };
  }
  if (normalized.includes("revoked")) {
    return { kind: "status", value: "revoked", source };
  }
  return { kind: "status", value: raw, label: humanize(raw), source };
};

export const selectorFact = (
  value: unknown,
  label?: string,
  source: FactSource = "decoded",
): ToolFact | null => {
  const selector =
    typeof value === "string" && value.startsWith("0x") && value.length >= 10
      ? value.slice(0, 10).toLowerCase()
      : null;
  return selector ? { kind: "selector", value: selector, label, source } : null;
};

export const calldataWord = (input: string, index: number): string | null => {
  const start = 10 + index * 64;
  const word = input.slice(start, start + 64);
  return word.length === 64 ? word : null;
};

export const addressFromWord = (word: string | null): string | null => {
  if (!word) return null;
  return normalizeAddress(`0x${word.slice(24)}`);
};

export const bigintFromWord = (word: string | null): string | null => {
  if (!word) return null;
  try {
    return BigInt(`0x${word}`).toString();
  } catch {
    return null;
  }
};

export const decodedValue = (result: Record<string, unknown>): unknown => {
  const decodedRoot = asRecord(result.result_decoded);
  const decoded = asRecord(decodedRoot?.decoded);
  return decoded?.decoded;
};

export const topicTokenFact = (topic: string): ToolFact | null => {
  const matches = topic.match(/\b[A-Z][A-Z0-9]{1,9}\b/g);
  const ignored = new Set(["URL", "USD"]);
  const token = matches?.find((match) => !ignored.has(match));
  return token ? { kind: "token", value: token, source: "label" } : null;
};

export const hostnameFromUrl = (urlText: string): string | null => {
  try {
    return new URL(urlText).hostname.replace(/^www\./, "");
  } catch {
    return null;
  }
};

import type { LucideIcon } from "lucide-react";
import type { ElementType } from "react";

export type ToolConfidence = "high" | "medium" | "fallback";

export type ToolChip = {
  label: string;
  dot?: string;
  icon?: ElementType;
};

export type InterpretedToolStep = {
  icon: LucideIcon;
  title: string;
  chips: ToolChip[];
  confidence: ToolConfidence;
  rawLabel: string;
  /** The tool reported a failure/error status (drives the red-X step marker). */
  failed: boolean;
};

export type ToolStepInput = {
  toolName: string;
  argsText?: string;
  result?: unknown;
  /** Earlier tool results in the same trace, used to resolve references such
   * as commit `tx_ids` back to the staged transaction's network. */
  relatedResults?: unknown[];
};

export type FactKind =
  | "action"
  | "address"
  | "amount"
  | "block"
  | "chain"
  | "cluster"
  | "code"
  | "count"
  | "decoded"
  | "gas"
  | "selector"
  | "skill"
  | "sourceHost"
  | "status"
  | "slot"
  | "token"
  | "txId";

export type FactRole =
  | "contract"
  | "decimals"
  | "error"
  | "from"
  | "metadata"
  | "native"
  | "null"
  | "owner"
  | "primary"
  | "recipient"
  | "results"
  | "secondary"
  | "spender"
  | "staged"
  | "to"
  | "tx";

export type FactSource = "args" | "decoded" | "label" | "result";

export type ToolFact = {
  kind: FactKind;
  role?: FactRole;
  value: string;
  label?: string;
  source: FactSource;
};

export type ToolOperation = {
  id: string;
  facts: ToolFact[];
  confidence: ToolConfidence;
  rawLabel: string;
  /**
   * Title that overrides the descriptor's. Only for families whose title
   * carries payload data (e.g. a delegation's child label), which a static
   * `fixedTitle` cannot express.
   */
  title?: string;
  /**
   * Forces the failed (red X) presentation. Families whose failure signal is
   * not a `failed`/`error` status fact set this explicitly.
   */
  failed?: boolean;
};

export type ToolContext = {
  rawLabel: string;
  parsedArgs: unknown;
  result: unknown;
  resultRecord: Record<string, unknown> | null;
  relatedResultRecords: Record<string, unknown>[];
};

export type ToolMatcher = (ctx: ToolContext) => ToolOperation | null;

