"use client";
import { useRef, useState } from "react";
import { useAomiRuntime } from "@aomi-labs/react";
import { useAomiWalletKit } from "../../lib/wallet-kit";
import { TransactionReview } from "./transaction-review";

/** Presents the next durable Action and submits only an explicit user choice. */
export function WalletReview() {
  const {
    pendingActions,
    actionAttempts,
    executeAction,
    rejectAction,
    showNotification,
  } = useAomiRuntime();
  const wallet = useAomiWalletKit();
  const liveAction = pendingActions[0];
  const attempt = liveAction ? actionAttempts.get(liveAction.id) : undefined;
  const lock = useRef(false);
  const [deciding, setDeciding] = useState(false);
  const approving =
    deciding ||
    attempt?.state === "executing" ||
    attempt?.state === "responding";

  const decide = async (approved: boolean) => {
    if (!liveAction || approving || lock.current) return;
    lock.current = true;
    setDeciding(true);
    try {
      if (approved) await executeAction(liveAction.id);
      else await rejectAction(liveAction.id, "Request rejected");
    } catch (error) {
      showNotification({
        type: "error",
        title:
          error instanceof Error ? error.message : "Action response failed",
        duration: 6000,
      });
    } finally {
      lock.current = false;
      setDeciding(false);
    }
  };

  if (!liveAction) return null;

  return (
    <TransactionReview
      action={liveAction}
      supportedChains={wallet.supportedChains}
      approving={approving}
      onApprove={() => void decide(true)}
      onReject={() => void decide(false)}
    />
  );
}

"use client";
import { useEffect, useRef } from "react";
import type { Action, ActionRequest } from "@aomi-labs/client";
import { Wallet, Fuel } from "lucide-react";
import { Button } from "../ui/button";
import { ImpactPanel } from "./wallet-impact";
import {
  type SupportedChain,
  visibleSimulationWarnings,
  compact,
  simulationCostSummary,
} from "./presentation";

export function TransactionReview({
  action,
  supportedChains,
  approving = false,
  onApprove,
  onReject,
}: {
  action: Action;
  supportedChains?: readonly SupportedChain[];
  approving?: boolean;
  onApprove: () => void;
  onReject: () => void;
}) {
  const reviewRef = useRef<HTMLElement>(null);
  useEffect(() => {
    const review = reviewRef.current;
    if (!review) return;
    // Reveal within the sidebar without moving the chat's clipping ancestors.
    const rail = review.closest<HTMLElement>(".aui-activity-sidebar");
    if (rail) {
      const overflow =
        review.getBoundingClientRect().bottom -
        rail.getBoundingClientRect().bottom;
      if (overflow > 0) rail.scrollTop += overflow + 16;
    }
  }, [action.id, action.revision]);
  const simulation =
    action.request.type === "sign" ? undefined : action.request.simulation;
  const warnings = visibleSimulationWarnings(simulation);
  const failed =
    simulation?.status === "failed" ||
    simulation?.guards.some((guard) => guard.status === "failed");
  const request = action.request;
  const signers =
    request.type === "sign"
      ? [request.signer]
      : request.type === "execute_evm"
        ? request.transactions.map((tx) => tx.from)
        : request.transactions.map((tx) => tx.payer);
  return (
    <section
      ref={reviewRef}
      data-testid="transaction-review"
      data-action-id={action.id}
      aria-label="Wallet impact"
      className="text-aomi-fg animate-in fade-in-0 slide-in-from-top-2 mt-3 min-w-0 duration-300 motion-reduce:animate-none"
    >
