          <Button
            type="button"
            onClick={onApprove}
            disabled={approving}
            className="bg-aomi-fg text-aomi-bg hover:bg-aomi-fg h-10 rounded-full text-[12px] hover:opacity-90"
          >
            <Wallet className="size-4" />
